{
  "name": "money-utils",
  "version": "1.0.0",
  "description": "Currency and money utilities for Frontier Verifier benchmark",
  "type": "module",
  "license": "MIT",
  "main": "src/index.ts",
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
  },
  "devDependencies": {
