export async function runConcurrentJitter<T>(
  operations: Array<() => Promise<T>>,
  maxJitterMs = 5
): Promise<T[]> {
  return Promise.all(
    operations.map(async (op) => {
      const delay = Math.random() * maxJitterMs;
      if (delay > 0) await new Promise((r) => setTimeout(r, delay));
      return op();
    })
  );
}

