import { createMoney, convertCurrency } from "./src/money.ts";

// Case from the issue: should round to 92.35, not truncate to 92.34
// 100 * 0.9235 = 92.35 exactly, but let's construct a case that triggers the bug
const money = createMoney(100, "USD");
const rates = { "USD_EUR": 0.92345 };
const result = convertCurrency(money, "EUR", rates);
console.log(`Expected: 92.35 (rounded), Got: ${result.amount}`);

// Also test a value that would truncate incorrectly
// e.g., 100 * 0.92356 = 92.356, should round to 92.36, floor gives 92.35
const rates2 = { "USD_EUR": 0.92356 };
const result2 = convertCurrency(money, "EUR", rates2);
console.log(`Expected: 92.36 (rounded), Got: ${result2.amount}`);

// Basic round-to-cents test
const money2 = createMoney(92.35, "EUR");
console.log(`92.35 from createMoney: ${money2.amount}`);

// Assert failure
if (result.amount !== 92.35) {
  console.error(`BUG CONFIRMED: got ${result.amount} instead of 92.35`);
  process.exit(1);
}

