import { describe, test, expect } from "vitest";
import { createMoney, convertCurrency, roundToCents, add, subtract, multiply } from "../src/money.ts";
import { runConcurrentJitter, generateBoundaryInputs } from "./fuzz-helpers.ts";

describe("Currency conversion rounding invariant", () => {
  test("convertCurrency always rounds, never truncates", () => {
    const cases: Array<{ amount: number; rate: number; expected: number }> = [
      { amount: 100, rate: 0.92345, expected: 92.35 },
      { amount: 100, rate: 0.92356, expected: 92.36 },
      { amount: 100, rate: 0.92350, expected: 92.35 },
      { amount: 50, rate: 1.505, expected: 75.25 },
      { amount: 1, rate: 0.99999, expected: 1.0 },
      { amount: 999999.99, rate: 0.9234, expected: 923399.99 },
      // Truncation trap: 9.995 * 100 = 999.5, floor=999 => 9.99, round=1000 => 10.00
      { amount: 10, rate: 0.99995, expected: 10.0 },
    ];

    for (const { amount, rate, expected } of cases) {
      const money = createMoney(amount, "USD");
      const result = convertCurrency(money, "EUR", { USD_EUR: rate });
      expect(result.amount).toBe(expected);
    }
  });

  test("convertCurrency result is always within ±0.01 of exact value", () => {
    const rates = { USD_EUR: 0.87654 };
    const amounts = [0.01, 1, 10, 100, 1000, 999999.99];

    for (const amount of amounts) {
      const money = createMoney(amount, "USD");
      const result = convertCurrency(money, "EUR", rates);
      const exact = amount * 0.87654;
      expect(Math.abs(result.amount - exact)).toBeLessThan(0.01);
    }
  });

  test("roundToCents always produces 2 decimal places", () => {
    const values = [0.1, 0.01, 0.001, 1.999, 2.675, 1.005, -1.555];
    for (const v of values) {
      const rounded = roundToCents(v);
      // Should not have more than 2 decimal places
      expect(rounded * 100 % 1).toBe(0);
    }
  });

  test("concurrent conversions are consistent", async () => {
    const rates = { USD_EUR: 0.92345 };
    const ops = Array.from({ length: 50 }, () => () => {
      const money = createMoney(100, "USD");
      return Promise.resolve(convertCurrency(money, "EUR", rates));
    });
    const results = await runConcurrentJitter(ops);
    for (const r of results) {
      expect(r.amount).toBe(92.35);
    }
  });

  test("boundary: zero amount conversion", () => {
    const money = createMoney(0, "USD");
    const result = convertCurrency(money, "EUR", { USD_EUR: 0.92 });
    expect(result.amount).toBe(0);
  });

  test("boundary: very small positive amount", () => {
    const money = createMoney(0.01, "USD");
    const result = convertCurrency(money, "EUR", { USD_EUR: 0.50001 });
    // 0.01 * 0.50001 = 0.0050001, should round to 0.01
    expect(result.amount).toBe(0.01);
  });

  test("boundary: negative amount conversion", () => {
    const money = createMoney(-100, "USD");
    const result = convertCurrency(money, "EUR", { USD_EUR: 0.92345 });
    expect(result.amount).toBe(-92.35);
  });
});

