{
  "name": "money-utils",
  "version": "1.0.0",
  "description": "Currency and money utilities for Frontier Verifier benchmark",
  "type": "module",
  "license": "MIT",
  "main": "src/index.ts",
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/bun": "latest"
  }
}

export interface Money {
  amount: number;
  currency: string;
}

export function createMoney(amount: number, currency: string): Money {
  if (typeof amount !== "number" || isNaN(amount)) throw new Error("Invalid amount");
  if (typeof currency !== "string" || currency.length !== 3) throw new Error(`Invalid currency: ${currency}`);
  return { amount: roundToCents(amount), currency: currency.toUpperCase() };
}

export function roundToCents(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

export function formatMoney(money: Money): string {
  const rounded = roundToCents(money.amount);
  return `${rounded.toFixed(2)} ${money.currency}`;
}

export function parseMoney(input: string): Money {
  if (typeof input !== "string") throw new Error("Input must be string");
  const trimmed = input.trim();
  const currencyMatch = trimmed.match(/\b([A-Z]{3})\b/i);
  if (!currencyMatch) throw new Error(`Could not parse currency from: ${input}`);
  const currency = currencyMatch[1]!.toUpperCase();
  let numericPart = trimmed.replace(new RegExp(currency, "i"), "").replace(/[$€£¥]/g, "").trim();
  numericPart = numericPart.replace(/,/g, "").trim();
  if (numericPart === "" || numericPart === "." || numericPart === "-") {
    throw new Error(`Could not parse amount from: ${input}`);
  }
  const amount = parseFloat(numericPart);
  if (isNaN(amount)) throw new Error(`Could not parse amount from: ${input}`);
  return { amount: roundToCents(amount), currency };
}

export function add(a: Money, b: Money): Money {
  if (a.currency !== b.currency) throw new Error(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  return { amount: roundToCents(a.amount + b.amount), currency: a.currency };
}

export function subtract(a: Money, b: Money): Money {
  if (a.currency !== b.currency) throw new Error(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  return { amount: roundToCents(a.amount - b.amount), currency: a.currency };
}

export function multiply(money: Money, factor: number): Money {
  if (typeof factor !== "number" || isNaN(factor)) throw new Error("Invalid factor");
  return { amount: roundToCents(money.amount * factor), currency: money.currency };
}

export function convertCurrency(money: Money, targetCurrency: string, rates: Record<string, number>): Money {
  const target = targetCurrency.toUpperCase();
  if (money.currency === target) return { ...money };
  const key = `${money.currency}_${target}`;
  const rate = rates[key];
  if (rate === undefined) throw new Error(`Missing exchange rate: ${key}`);
  const converted = money.amount * rate;
  // BUG: truncates instead of rounding
  return { amount: Math.floor(converted * 100) / 100, currency: target };
}

import { describe, test, expect } from "vitest";
import { createMoney, formatMoney, parseMoney, add, subtract, multiply, convertCurrency, roundToCents } from "../src/money.ts";

describe("money-utils", () => {
  test("roundToCents rounds half-up", () => {
    expect(roundToCents(1.005)).toBe(1.01);
    expect(roundToCents(1.004)).toBe(1.0);
    expect(roundToCents(2.675)).toBe(2.68);
  });

  test("formatMoney formats to 2 decimals", () => {
    expect(formatMoney({ amount: 10, currency: "USD" })).toBe("10.00 USD");
    expect(formatMoney({ amount: 10.5, currency: "EUR" })).toBe("10.50 EUR");
    expect(formatMoney({ amount: 1.005, currency: "USD" })).toBe("1.01 USD");
  });

  test("parseMoney handles comma-separated", () => {
    expect(parseMoney("1,000.00 USD")).toEqual({ amount: 1000, currency: "USD" });
    expect(parseMoney("$1,234.56 USD")).toEqual({ amount: 1234.56, currency: "USD" });
    expect(parseMoney("USD 2,500.99")).toEqual({ amount: 2500.99, currency: "USD" });
  });

  test("parseMoney handles simple amounts", () => {
    expect(parseMoney("100 USD")).toEqual({ amount: 100, currency: "USD" });
    expect(parseMoney("99.99 EUR")).toEqual({ amount: 99.99, currency: "EUR" });
  });

  test("add validates currency mismatch", () => {
    const a = createMoney(10, "USD");
    const b = createMoney(5, "EUR");
    expect(() => add(a, b)).toThrow(/Currency mismatch/);
    expect(add(a, createMoney(5, "USD"))).toEqual({ amount: 15, currency: "USD" });
  });

  test("subtract validates currency", () => {
    expect(() => subtract(createMoney(10, "USD"), createMoney(5, "EUR"))).toThrow();
  });

  test("multiply", () => {
    expect(multiply(createMoney(10, "USD"), 2.5)).toEqual({ amount: 25, currency: "USD" });
  });

  test("convertCurrency precision", () => {
    const m = createMoney(100, "USD");
    const rates = { "USD_EUR": 0.9234, "EUR_USD": 1.083 };
    expect(convertCurrency(m, "EUR", rates)).toEqual({ amount: 92.34, currency: "EUR" });
    // large amount: 999999.99 * 0.9234 = 923399.990766 -> 923399.99 after rounding
    const large = createMoney(999999.99, "USD");
    expect(convertCurrency(large, "EUR", rates).amount).toBe(923399.99);
    // same currency no conversion
    expect(convertCurrency(m, "USD", rates)).toEqual(m);
    expect(convertCurrency(m, "usd", rates)).toEqual(m);
  });

  test("convertCurrency throws missing rate", () => {
    expect(() => convertCurrency(createMoney(10, "USD"), "JPY", {})).toThrow(/Missing exchange rate/);
  });

  test("createMoney validates", () => {
    expect(() => createMoney(NaN, "USD")).toThrow();
    expect(() => createMoney(10, "US")).toThrow();
  });
});

